from pathlib import Path
p=Path('outputs/bia_campaign_progress.md');s=p.read_text(encoding='utf-8');s+='\n\nStage43N3: Stage43M에서 챕터 재시작을 건너뛰기 입력 없이 검사해 동일 오류를 재현했습니다. 챕터 힙을 비운 뒤에도 전역 엔진 참조(0x08CE5B10)가 해제된 객체(0x08FEA540)를 가리켰고, 영상 데이터가 그 영역을 덮었습니다. 영상 종료 시 0x088160A8에서 0xFE230038로 잘못된 호출을 시도하는 것을 중단점으로 포착했습니다. 오래된 전역 참조를 0으로 바꾸고 해당 검사부터 다시 실행하면 새 엔진·뷰포트 객체가 정상 생성되었습니다. 진단 자료: stage43n3_restart/restart_diagnosis.json.\n\nStage43O: 챕터 힙 초기화 시 엔진 참조도 초기화하는 수정 후보를 만들었습니다. 기존 문자열·글꼴·섹션 데이터 및 재배치 정보를 보존했고, 상대 주소 이동 조건 3건의 코드 실행 검사를 통과했습니다. 후보 ISO: PROJECT_ROOT/BIA_STAGE43O_RESTART_LIFETIME_TEST.iso. 실제 재시작 검증 진행 중이며 완료본으로 아직 채택하지 않았습니다.\n';p.write_text(s,encoding='utf-8')
